      "evidenceAgainst": []
    },
    {
      "label": "Instrument‑specific weekly thermal or mechanical cycle",
      "probability": 0.15,
      "rationale": "Both pendulum_lab and resonator_obs reside in enclosures that may undergo a weekly temperature/power cycle, potentially imprinting a periodic pattern. However, such cycles would not normally yield exact numeric repetition to the micro‑unit precision observed.",
